import React, { useCallback, useEffect, useRef, useState } from 'react';
import { dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import { usePeriodJobPermissions } from '../../../hooks/usePeriodJobPermissions';
import { useAppDispatch } from '../../../store/hooks';
import { PeriodActionPanel } from '../../../components/kt/PeriodActionPanel';
import { CarryOverPreviewSection } from '../../../components/kt/CarryOverPreviewSection';
import { ktService } from '../../../services/kt/ktService';
import type { CarryOverPreviewLineDto } from '../../../services/kt/models';
import { PERIOD_JOB_TYPES } from '../../../constants/periodJobTypes';
import { periodPageLabels as L } from '../../../constants/periodPageLabels';
import { carryOverStatusLabel } from '../../../utils/periodProcessStatusLabel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';

const CarryOverPreviewBlock: React.FC<{ year: number; testIdPrefix: string }> = ({
  year,
  testIdPrefix,
}) => {
  const dispatch = useAppDispatch();
  const [lines, setLines] = useState<CarryOverPreviewLineDto[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [loadErrorMessage, setLoadErrorMessage] = useState<string | undefined>();
  const loadErrorToastShownRef = useRef(false);

  useEffect(() => {
    let cancelled = false;
    loadErrorToastShownRef.current = false;
    const t = setTimeout(() => {
      setLoading(true);
      setLoadFailed(false);
      setLoadErrorMessage(undefined);
      ktService.getCarryOverPreview(year)
        .then(data => {
          if (!cancelled) {
            loadErrorToastShownRef.current = false;
            setLines(data);
            setLoadFailed(false);
          }
        })
        .catch(err => {
          if (!cancelled) {
            setLines([]);
            setLoadFailed(true);
            const msg = getApiErrorMessage(err, L.carryOver.previewLoadError);
            setLoadErrorMessage(msg);
            if (!loadErrorToastShownRef.current) {
              loadErrorToastShownRef.current = true;
              dispatchAppToast(dispatch, { message: msg, type: 'error' });
            }
          }
        })
        .finally(() => { if (!cancelled) setLoading(false); });
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [year, dispatch]);

  return (
    <CarryOverPreviewSection
      sourceYear={year}
      targetYear={year + 1}
      lines={lines}
      loading={loading}
      loadFailed={loadFailed}
      loadErrorMessage={loadErrorMessage}
      testIdPrefix={testIdPrefix}
    />
  );
};

const ChuyenSoDuPage: React.FC = () => {
  const { canRun } = usePeriodJobPermissions('carry-over');
  const getStatus = useCallback(
    async (_m: number, y: number) => carryOverStatusLabel(await ktService.getCarryOverStatus(y)),
    [],
  );

  return (
    <PeriodActionPanel
      testIdPrefix="kt-chuyen-so-du"
      title="Chuyển số dư"
      icon="fa-random"
      description="Chuyển số dư cuối năm sang OpeningBalances năm mới — không sinh phiếu kế toán."
      showMonth={false}
      runLabel="Chuyển số dư"
      jobType={PERIOD_JOB_TYPES.CarryOver}
      gateMonth={12}
      jobStatusMonth={() => 0}
      getStatus={getStatus}
      onRun={(_m, y) => ktService.executeCarryOver(y)}
      runPermitted={canRun}
      renderExtra={({ year }) => (
        <CarryOverPreviewBlock year={year} testIdPrefix="kt-chuyen-so-du" />
      )}
    />
  );
};

export default ChuyenSoDuPage;
